import { useEffect, useMemo, useState } from 'react';
import { Routes, Route, NavLink, Navigate, useLocation, useNavigate } from 'react-router-dom';
import Dashboard from './pages/Dashboard';
import Copilot from './pages/Copilot';
import WorkOrderAtp from './pages/WorkOrderAtp';
import BomExplorer from './pages/BomExplorer';
import BomExplorerStreamlitParity from './pages/BomExplorerStreamlitParity';
import ShortageAgent from './pages/ShortageAgent';
import CrossSiteTransfer from './pages/CrossSiteTransfer';
import { login as apiLogin, me as apiMe, type Persona } from './api/authApi';
import ErrorBoundary from './components/ErrorBoundary';
import GlobalCopilotDrawer from './components/GlobalCopilotDrawer';
import { getDataSource, setDataSource, subscribeDataSource, type DataSource } from './api/dataSource';

type Session = { name: string; role: Persona };
type NavItem = { to: string; label: string; roles: Persona[] };

const SESSION_KEY = 'rtb_session_v1';
const TOKEN_KEY = 'rtb_auth_token';

const navItems: NavItem[] = [
  { to: '/', label: 'Overview', roles: ['admin', 'planner', 'sourcing', 'exec'] },
  { to: '/copilot', label: 'Copilot', roles: ['admin', 'planner', 'sourcing', 'exec'] },
  { to: '/wo-atp', label: 'WO-CTB', roles: ['admin', 'planner'] },
  { to: '/bom', label: 'BOM Explorer', roles: ['admin', 'planner', 'sourcing'] },
  { to: '/shortages', label: 'Shortage Agent', roles: ['admin', 'sourcing'] },
  { to: '/transfer', label: 'Cross-Site Transfer', roles: ['admin', 'planner', 'sourcing'] },
];

function Login({ onLogin }: { onLogin: (session: Session, token: string) => void }) {
  const [userId, setUserId] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {
      const r = await apiLogin(userId.trim(), password);
      onLogin(r.user, r.access_token);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Sign-in failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        minHeight: 'calc(100vh - 24px)',
        display: 'grid',
        placeItems: 'center',
        background:
          'radial-gradient(1200px 500px at 10% -10%, rgba(59,130,246,.16), transparent 60%), radial-gradient(900px 500px at 100% 0%, rgba(236,72,153,.12), transparent 60%), #f8fafc',
        borderRadius: 18,
        padding: 20,
      }}
    >
      <form
        onSubmit={submit}
        style={{
          width: 'min(460px, 92vw)',
          background: 'linear-gradient(180deg, #ffffff 0%, #f8fafc 100%)',
          border: '1px solid #dbe6f3',
          borderRadius: 22,
          padding: 30,
          boxShadow: '0 18px 50px rgba(15,23,42,.10), 0 2px 8px rgba(15,23,42,.05)',
        }}
      >
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
          <span
            style={{
              display: 'inline-block',
              width: 8,
              height: 8,
              borderRadius: 999,
              background: '#2563eb',
              boxShadow: '0 0 0 6px rgba(37,99,235,.15)',
            }}
          />
          <div style={{ fontSize: 12, fontWeight: 800, letterSpacing: 0.6, color: '#1e40af' }}>SECURE SIGN IN</div>
        </div>

        <div style={{ fontSize: 32, fontWeight: 900, color: '#0f172a', marginBottom: 8, letterSpacing: -0.6 }}>ReadyToBuild</div>
        <div style={{ fontSize: 14, color: '#475569', marginBottom: 12, lineHeight: 1.5 }}>
          Welcome back. Sign in with your user credentials to access your role-based workspace.
        </div>
        <div
          style={{
            fontSize: 12,
            color: '#64748b',
            marginBottom: 24,
            lineHeight: 1.5,
            padding: '10px 12px',
            borderRadius: 10,
            background: '#f1f5f9',
            border: '1px solid #e2e8f0',
          }}
        >
          Demo: <strong>admin.user</strong> / <strong>readytobuild</strong> (also planner.user, sourcing.user, exec.user)
        </div>

        <label style={{ fontSize: 12, fontWeight: 800, color: '#334155', letterSpacing: 0.4 }}>USER ID</label>
        <input
          value={userId}
          onChange={(e) => setUserId(e.target.value)}
          placeholder="Enter user ID"
          style={{
            width: '100%',
            marginTop: 8,
            marginBottom: 16,
            height: 44,
            borderRadius: 12,
            border: '1px solid #cbd5e1',
            background: '#fff',
            padding: '0 12px',
            fontSize: 14,
          }}
        />

        <label style={{ fontSize: 12, fontWeight: 800, color: '#334155', display: 'block', letterSpacing: 0.4 }}>PASSWORD</label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Enter password"
          style={{
            width: '100%',
            marginTop: 8,
            height: 44,
            borderRadius: 12,
            border: '1px solid #cbd5e1',
            background: '#fff',
            padding: '0 12px',
            fontSize: 14,
          }}
        />

        {error ? (
          <div
            style={{
              marginTop: 12,
              fontSize: 12,
              color: '#b91c1c',
              background: '#fef2f2',
              border: '1px solid #fecaca',
              borderRadius: 10,
              padding: '8px 10px',
            }}
          >
            {error}
          </div>
        ) : null}

        <button
          type="submit"
          disabled={loading}
          style={{
            marginTop: 20,
            width: '100%',
            height: 46,
            fontSize: 15,
            fontWeight: 800,
            borderRadius: 12,
            border: 'none',
            color: '#fff',
            background: loading ? '#93c5fd' : 'linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)',
            boxShadow: loading ? 'none' : '0 8px 18px rgba(37,99,235,.32)',
          }}
        >
          {loading ? 'Signing In...' : 'Sign In'}
        </button>

        <div style={{ marginTop: 14, fontSize: 12, color: '#64748b', textAlign: 'center' }}>
          Access is automatically mapped to your assigned persona.
        </div>
      </form>
    </div>
  );
}

const YASH_LOGO_B64 = ''; // Paste base64 PNG here later (no data prefix)

export default function App() {
  const location = useLocation();
  const navigate = useNavigate();
  const [session, setSession] = useState<Session | null>(() => {
    try {
      const raw = window.localStorage.getItem(SESSION_KEY);
      return raw ? (JSON.parse(raw) as Session) : null;
    } catch {
      return null;
    }
  });

  useEffect(() => {
    const token = window.localStorage.getItem(TOKEN_KEY);
    if (!token) return;
    apiMe(token)
      .then((user) => setSession(user))
      .catch(() => {
        window.localStorage.removeItem(TOKEN_KEY);
        window.localStorage.removeItem(SESSION_KEY);
        setSession(null);
      });
  }, []);

  const onLogin = (next: Session, token: string) => {
    setSession(next);
    try {
      window.localStorage.setItem(SESSION_KEY, JSON.stringify(next));
      window.localStorage.setItem(TOKEN_KEY, token);
    } catch {
      /* ignore */
    }
    navigate('/', { replace: true });
  };

  const onLogout = () => {
    setSession(null);
    try {
      window.localStorage.removeItem(SESSION_KEY);
      window.localStorage.removeItem(TOKEN_KEY);
    } catch {
      /* ignore */
    }
    navigate('/', { replace: true });
  };

  const allowedNavItems = useMemo(
    () => navItems.filter((n) => (session ? n.roles.includes(session.role) : false)),
    [session],
  );

  // Data source selection (Snowflake / Fabric). Every API call in
  // ctbApi.ts/aiApi.ts/transferApi.ts reads this same value automatically
  // (see api/dataSource.ts) - this state is only here to re-render the
  // dropdown and clear cached data when the user switches.
  const [dataSource, setDataSourceState] = useState<DataSource>(getDataSource());
  useEffect(() => subscribeDataSource(setDataSourceState), []);

  const canAccess = (path: string) =>
    session ? navItems.some((n) => n.to === path && n.roles.includes(session.role)) : false;

  if (!session) {
    return (
      <main className="page-container">
        <Routes>
          <Route path="*" element={<Login onLogin={onLogin} />} />
        </Routes>
      </main>
    );
  }

  if (location.pathname === '/login') return <Navigate to="/" replace />;

  return (
    <>
      <header className="app-header">
        <div className="app-header-inner">
          <div className="app-brand">
            {YASH_LOGO_B64 ? (
              <img
                className="app-brand-mark"
                src={YASH_LOGO_B64.startsWith('data:image') ? YASH_LOGO_B64 : `data:image/png;base64,${YASH_LOGO_B64}`}
                alt="YASH"
              />
            ) : null}
            <div className="app-brand-title">ReadyToBuild</div>
          </div>

          <nav className="app-nav" aria-label="Primary">
            {allowedNavItems.map((n) => (
              <NavLink
                key={n.to}
                to={n.to}
                end={n.to === '/'}
                className={({ isActive }) => `app-nav-link${isActive ? ' active' : ''}`}
              >
                {n.label}
              </NavLink>
            ))}
          </nav>

          <div className="app-user">
            <div className="app-datasource" title="Data source">
              <select
                aria-label="Data source"
                value={dataSource}
                onChange={(e) => setDataSource(e.target.value as DataSource)}
              >
                <option value="snowflake">Snowflake</option>
                <option value="fabric">Fabric</option>
              </select>
            </div>

            <div className="app-user-meta">
              <div className="app-user-name">{session.name}</div>
              <div className="app-user-role">{session.role.toUpperCase()}</div>
            </div>

            <div className="app-avatar" aria-label="User">
              {String(session.name || '?')
                .trim()
                .split(/\s+/)
                .slice(0, 2)
                .map((p) => p[0]?.toUpperCase())
                .join('')}
            </div>

            <button type="button" className="secondary app-logout" onClick={onLogout}>
              Logout
            </button>
          </div>
        </div>
      </header>

      <GlobalCopilotDrawer />

      <main className="page-container">
        <ErrorBoundary>
          <Routes>
            <Route path="/" element={canAccess('/') ? <Dashboard /> : <Navigate to="/copilot" replace />} />
            <Route path="/copilot" element={canAccess('/copilot') ? <Copilot /> : <Navigate to="/" replace />} />
            <Route path="/wo-atp" element={canAccess('/wo-atp') ? <WorkOrderAtp /> : <Navigate to="/" replace />} />
            <Route path="/bom" element={canAccess('/bom') ? <BomExplorerStreamlitParity /> : <Navigate to="/" replace />} />
            <Route path="/shortages" element={canAccess('/shortages') ? <ShortageAgent /> : <Navigate to="/" replace />} />
            <Route path="/transfer" element={canAccess('/transfer') ? <CrossSiteTransfer /> : <Navigate to="/" replace />} />
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </ErrorBoundary>
      </main>
    </>
  );
}
